{
["Nilable"] = false,
["Name"] = "swingType",
["Type"] = "PlayerSwingType",
},
{
["Documentation"] = {
"Whether the current target is within auto attack range. Should not be used if the 'checksRange' parameter is false.",
},
["Nilable"] = false,
["Name"] = "isInRange",
["Type"] = "bool",
},
{
["Documentation"] = {
"Can be false if a range check was not made for any reason, for example there is not a current target.",
},
["Nilable"] = false,
["Name"] = "checksRange",
["Type"] = "bool",
},
},
["SynchronousEvent"] = true,
["Documentation"] = {
"Only signaled for swing types that have an active range check. See C_SwingTimer.EnableRangeCheck.",
},
},
},
["Tables"] = {
{
["Type"] = "Enumeration",
["Name"] = "PlayerSwingType",
["MaxValue"] = 2,
["Fields"] = {
{
["Type"] = "PlayerSwingType",
["EnumValue"] = 0,
["Name"] = "MainHand",
},
{
["Type"] = "PlayerSwingType",
["EnumValue"] = 1,
["Name"] = "OffHand",
},
{
["Type"] = "PlayerSwingType",
["EnumValue"] = 2,
["Name"] = "Ranged",
},
},
["NumValues"] = 3,
["MinValue"] = 0,
},
},
["Predicates"] = {
},
["Name"] = "SwingTimer",
["Namespace"] = "C_SwingTimer",
["Functions"] = {
{
["Type"] = "Function",
["Name"] = "EnableRangeCheck",
["SecretArguments"] = "AllowedWhenUntainted",
["Documentation"] = {
"Used in conjunction with PlayerSwingRangeUpdate to inform the UI when the current target goes in or out of auto attack range.",
},
["Arguments"] = {
{
["Nilable"] = false,
["Name"] = "swingType",
["Type"] = "PlayerSwingType",
},
{
["Documentation"] = {
"True if changes in range for the swing type should dispatch PlayerSwingRangeUpdate. False if the swing type no longer needs the event.",
},
["Nilable"] = false,
["Name"] = "enable",
["Type"] = "bool",
},
},
},
{
["Type"] = "Function",
["Name"] = "IsTargetWithinSwingRange",
["SecretArguments"] = "AllowedWhenUntainted",
["Returns"] = {
{
["Documentation"] = {
"Nil when no range check could be made, for example there is no target, the target cannot be attacked, or no weapon is equipped for the swing type. Nil must not be treated as out of range.",
},
["Nilable"] = true,
["Name"] = "isInRange",
["Type"] = "bool",
},
},
["Documentation"] = {
"Whether the current target is within range of the player's auto attack for the given swing type. Auto attacks only ever apply to the current target, so no other unit can be queried.",
},
["Arguments"] = {
{
["Nilable"] = false,
["Name"] = "swingType",
["Type"] = "PlayerSwingType",
},
},
},
},
},
